/**
 * Thread-safe mobile/spatial session wrapping `wordcraft_engine::Session`.
 */
public protocol MobileDocumentSessionProtocol: AnyObject, Sendable {
    
    /**
     * Selects the word at `(x_pt, y_pt)` on `page_index`.
     */
    func doubleTapAt(pageIndex: UInt32, xPt: Float, yPt: Float) throws  -> SelectionGeometry
    
    /**
     * Moves either the start (`is_anchor == true`) or end (`is_anchor == false`) selection handle.
     */
    func dragSelectionHandle(isAnchor: Bool, pageIndex: UInt32, xPt: Float, yPt: Float) throws  -> SelectionGeometry
    
    /**
     * Executes any `wordcraft-engine` command by ID and JSON parameters, returning
     * the updated document metrics, selection geometry, and `format.state` snapshot.
     */
    func executeCommand(cmdId: String, paramsJson: String) throws  -> CommandOutcome
    
    /**
     * Exports the active document to PDF bytes via `wordcraft_pdf`.
     */
    func exportPdfBytes() throws  -> Data
    
    /**
     * Returns exact page dimensions, section margins, and active paragraph indents in points.
     */
    func getRulerMetrics(pageIndex: UInt32) throws  -> RulerMetrics
    
    /**
     * Returns the current caret and selection highlight rectangles without mutating state.
     */
    func getSelectionGeometry()  -> SelectionGeometry
    
    /**
     * Commits text from the platform IME (`InputConnection` / `UITextInput`) as an IME edit.
     */
    func imeCommitText(text: String, joinWithPrevious: Bool) throws  -> CommandOutcome
    
    /**
     * Deletes `before` characters backward and `after` characters forward around the caret for IME sync.
     */
    func imeDeleteSurrounding(before: UInt32, after: UInt32) throws  -> CommandOutcome
    
    func isDirty()  -> Bool
    
    func pageCount()  -> UInt32
    
    func pageSizePt(pageIndex: UInt32) throws  -> PageSizePt
    
    /**
     * Renders a tile specified by `req` into straight RGBA8888 bytes.
     */
    func renderTile(req: TileRequest) throws  -> Data
    
    /**
     * Saves the active document as `.docx` bytes.
     */
    func saveDocxBytes() throws  -> Data
    
    /**
     * Places the caret at `(x_pt, y_pt)` on `page_index`.
     */
    func tapAt(pageIndex: UInt32, xPt: Float, yPt: Float) throws  -> SelectionGeometry
    
    /**
     * Selects the paragraph at `(x_pt, y_pt)` on `page_index`.
     */
    func tripleTapAt(pageIndex: UInt32, xPt: Float, yPt: Float) throws  -> SelectionGeometry
    
    func wordCount()  -> UInt64
    
}
