/**
 * Error returned across the FFI boundary without panicking.
 */
public 
enum MobileFfiError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case InvalidJson(detail: String
    )
    case IoFailed(detail: String
    )
    case CommandFailed(detail: String
